func documentsCreateUploadCommand() *cli.Command {
	return &cli.Command{
		Name:  "create-upload",
		Usage: "Call Documents.CreateUpload",
		Flags: append([]cli.Flag{
			&cli.StringFlag{Name: "name"},
			&cli.StringFlag{Name: "content-type"},
			&cli.StringMapFlag{Name: "meta"},
		}, fileFlag()...),
		Action: func(ctx context.Context, cmd *cli.Command) error {
			httpClient, endpoint, err := getClientConfig(ctx, cmd, "repository")
			if err != nil {
				return err
			}

			client := repository.NewDocumentsProtobufClient(endpoint, httpClient)

			var req repository.CreateUploadRequest

			if err := readRequest(cmd, &req); err != nil {
				return err
			}
			if cmd.String("file") == "" {
				req.Name = cmd.String("name")
				req.ContentType = cmd.String("content-type")
				if v := cmd.StringMap("meta"); len(v) > 0 {
					req.Meta = v
				}
			}

			res, err := client.CreateUpload(ctx, &req)
			if err != nil {
				return fmt.Errorf("call create-upload: %w", err)
			}

			return writeResponse(cmd, res)
		},
	}
}

